bool correctBracketing(String brackets) {
  if (brackets.length % 2 != 0) return false;

  int balance = 0;
  for (int i = 0; i < brackets.length; i++) {
    final char = brackets[i];

    if (char == '(' || char == '[' || char == '{') {
      balance++;
    } else if (char == ')' || char == ']' || char == '}') {
      balance--;

      if (balance < 0) return false;
    }
  }

