bool correctBracketing(String brackets) {
  if (brackets.length % 2 != 0) return false;

  final stack = Stack<String>();

  for (int i = 0; i < brackets.length; i++) {
    String bracket = brackets[i];

    switch (bracket) {
      case '(':
        stack.add(bracket);
        break;
      case ')':
        if (stack.isEmpty || stack.pop() != '(') {
          return false;
        }
        break;
      case '[':
        stack.add(bracket);
        break;
      case ']':
