          return false;
        }
        break;
      case '{':
        stack.add(bracket);
        break;
      case '}':
        if (stack.isEmpty || stack.pop() != '{') {
          return false;
        }
        break;
      default:
        // Ignore other characters
        continue;
    }
  }

  return stack.isEmpty;
}

