int dfs(
  List<List<int>> grid,
  List<bool> visited,
  int row,
  int col,
  int rows,
  int cols,
  int capacity,
  int remainingCapacity,
) {
  final index = row * cols + col;

  if (row < 0 || row >= rows || col < 0 || col >= cols ||
      visited[index] || grid[row][col] == -1 || 
      (grid[row][col] > remainingCapacity)) {
    return 0;
  }

  visited[index] = true;

  var count = 1;

  // Check adjacent cells
  const directions = [
    [-1, 0], [1, 0], [0, -1], [0, 1],
  ];

  for (final dir in directions) {
    final newRow = row + dir[0];
    final newCol = col + dir[1];

    count += dfs(grid, visited, newRow, newCol, rows, cols, capacity, remainingCapacity);
  }

  return count;
}

