String solve(String s) {
  if (s.isEmpty || s.length == 1) return 'YES';

  int n = s.length;
  List<int> count = List.filled(26, 0);

  for (int i=0; i <n; ++i) {
    count[s[i].codeUnitAt(0) - 'a'.codeUnitAt(0)]++;
  }

  bool isPalindrome = true;
  while (count[0] > 0 && count[25] > 0) {
    count[0]--;
    count[25]--;
    isPalindrome &= (s[0] == s[n-1]);
    s = s.substring(1, n-1);
    n -= 2;
  }

  while (isPalindrome && n >= 3) {
    int left = 0;
    int right = n - 1;

    while (left < right) {
      if (s[left] != s[right]) {
        isPalindrome = false;
        break;
      }
      left++;
      right--;
    }

    if (!isPalindrome) break;

    // Count the number of characters on one side
    int cnt = 0;
    while (cnt < n/2 && s[cnt] == s[cnt + 1]) cnt++;

    if (cnt < n/2) { 
      isPalindrome = false;
      break;
    }

    s = s.substring(cnt+1, n-cnt-1);
    n = n - 2*(cnt+1);
  }

  return isPalindrome ? 'YES' : 'NO';
}

